WITH deduped AS (SELECT id, customer_id, account_type, opened_date FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_type, status ORDER BY opened_date DESC, id) AS rank_in_group FROM accounts) ranked WHERE rank_in_group = 1) SELECT s.id, s.customer_id, s.account_type, s.opened_date, CASE WHEN account_type RLIKE '^(SAVINGS|LOAN)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS account_type_zone, (SELECT MIN(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS min_subscription_monthly_fee FROM deduped s
